import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st; int T = Integer.parseInt(br.readLine()); PrintWriter out = new PrintWriter(System.out); while (T-- > 0) { int N = Integer.parseInt(br.readLine()); int[] counts = new int[N + 1]; st = new StringTokenizer(br.readLine()); for (int i = 0; i < 2 * N; i++) { int val = Integer.parseInt(st.nextToken()); if (val <= N) counts[val]++; } int mex = 0; while (mex <= N && counts[mex] > 0) { mex++; } boolean possible = true; for (int i = 0; i < mex; i++) { if (counts[i] < 2) { possible = false; break; } } if (possible) { out.println("YES"); } else { out.println("NO"); } } out.flush(); out.close(); } }